<?php require_once __DIR__.'/includes/bootstrap.php';$sent=false;$error='';if(is_post()){verify_csrf();public_form_guard($db, 'contact', $_POST['recaptcha_token'] ?? '');$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$message)$error='Please complete all fields with a valid email.';else $sent=true;}?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Contact</div><h1>Talk to a WDH Specialist</h1><p>Tell us what you need and our team will get back to you.</p><?php if($sent):?><div class="alert success-alert">Thanks! Your message has been received.</div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="auth-card" style="max-width:720px"><form method="post"><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('contact')?><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Message<textarea name="message" rows="7" required></textarea></label><button class="btn primary">Send Message →</button></form></section></main><?php require __DIR__.'/includes/footer.php';?></body></html>
